def num_decodings(digits):
    # Walk the digits once. `current` is the number of readings of the digits seen so far,
    # `previous` the number for the digits before the latest one. The empty start has one reading.
    previous, current = 0, 1
    for i, digit in enumerate(digits):
        readings = 0
        if digit != "0":
            readings += current                           # this digit is a letter on its own (1 to 9)
        if i > 0 and 10 <= int(digits[i - 1:i + 1]) <= 26:
            readings += previous                          # this digit and the one before it form a letter (10 to 26)
        previous, current = current, readings
    return current
